import { getPathInfo } from "../address/PathInfo";
import { IPathInfo } from "../address/types";
import { IStateElement } from "../components/types";
import { setMountedScopeHost } from "../list/loopContextByNode";
import { DELIMITER, MODIFIER_READONLY, RECURSION_WILDCARD, STATE_STREAMS_NAME, STATE_UPDATED_CALLBACK_NAME, WILDCARD } from "../define";
import { normalizeDeclarationAliases } from "../declarationAliases";
import { raiseError } from "../raiseError";
import { IBindingInfo } from "../types";
import { findMountEntry, IMountEntry, translateByMountEntry } from "./mountEntries";

/**
 * webComponent/mount.ts — マウント記録（Phase 2・docs/state-mount-design.md §5、impl-plan §3-0）。
 *
 * v2 の不変条件「マウントされたコンポーネントのバインディングは、その位置にテンプレートを
 * 展開してパスに接頭辞を付けたものと区別できない」を、**バインディングの変換**として実装する。
 * マウントされたスコープのバインディングは登録時にここの `translateInnerPath` で
 * 親ツリーの絶対パスへ書き換えられ、以後は台帳・依存グラフ・キャッシュ・LIS・プールの
 * どれから見ても「親スコープにインラインで書かれた binding」と同一になる。
 *
 * 例外は私有キーと getter / メソッド（展開したテンプレートには存在しないもの）で、
 * これらは **予約セグメント**（D20・`#m<id>` — `#` はパス文法で書けない）を挟んだ
 * 絶対アドレスに載る。ツリーのアドレスと構造的に衝突せず、親 handler のオーバーレイ
 * dispatch はマーカーを含む読み書きだけに掛かる。D10（スコープ外から見えない）は
 * このアドレス空間の帰結になる。
 *
 * マーカーの位置は「ワイルドカード接頭辞の直後」:
 * - 単純な getter / 私有キー（`display` / `editing`）→ `<rootOuter>.#m.display`
 *   （ルートエントリが無い部分マウントのみの形では `#m.display`）
 * - ツリーのリストの上のワイルドカード getter（`get "children.*.label"`、`state: group`）
 *   → `group.children.*.#m.label` — ワイルドカード親がツリーのリストと一致するので、
 *   ループ文脈の解決（indexByWildcardPath）と listIndex の arity が素の getter と同じに保たれる
 * - 私有配列の上のワイルドカード getter（`state = { drafts: [] }` ＋ `get "drafts.*.title"`）
 *   → `<rootOuter>.#m.drafts.*.title` — 配列ごと私有側に閉じる
 */

export type { IMountEntry } from "./mountEntries";

export interface IMountRecord {
  readonly id: number;
  /** D20 の予約セグメント（`#m<id>`） */
  readonly marker: string;
  readonly component: Element;
  readonly stateProp: string;
  readonly parentStateElement: IStateElement;
  /** マウント表（内側接頭辞の長い順 — 最長接頭辞一致は先頭ヒットで決まる） */
  readonly entries: readonly IMountEntry[];
  /** ルートエントリ（`state: path`）。無ければ null（部分マウントのみ） */
  readonly rootEntry: IMountEntry | null;
  /** Δ ＝ ルート接頭辞のワイルドカード数（`$n` のスコープ補正が読む唯一の値） */
  readonly delta: number;
  /** 私有キー・単純 getter を載せるマーカーパス（`users.*.#m3` / `#m3`） */
  readonly markerBasePath: string;
  /** 作者の state オブジェクト（私有キー・getter・メソッドの実体） */
  readonly stateObject: Record<string, any>;
  readonly getterKeys: ReadonlySet<string>;
  readonly setterKeys: ReadonlySet<string>;
  /**
   * 完了前の親の初期適用（積み）が作者のオブジェクトに**注入した**キー
   * （webComponent/preCompletionWrites.ts）。作者のものではないので私有にしない
   * （v2 は厳格 R1: 作者が宣言した own data key は部分マウントに覆われていても私有 —
   * 設計書 §4-1 規則 2。1.x の「マッピングが勝つ」からの反転は D19 が予告済み）。
   */
  readonly injectedKeys: ReadonlySet<string>;
  /** 部分エントリが明示したキー（先頭セグメント）。同名の own data key より優先する（要件 B14 ②） */
  readonly mappedKeys: ReadonlySet<string>;
  /**
   * 私有データの初期スナップショット（own data key の浅い複製・D21）。
   * マウントインスタンス（listIndex）ごとの私有オブジェクトはここから複製される。
   */
  readonly privateSnapshot: Readonly<Record<string, unknown>>;
  /**
   * マーカーの親パス（翻訳後） → { 接尾キー → 作者のアクセサ情報 }。
   * `display` は markerBase の親に `display → display`、
   * ワイルドカード getter `"children.*.label"` は `group.children.*` に `label → children.*.label`。
   * `indexShift` は翻訳で増えたワイルドカード数（アクセサ内の `$n` のスコープ補正が読む）。
   * translateInnerPath のマーカー化で遅延登録され、オーバーレイの get とトラップが引く。
   */
  readonly accessorBySuffixByMarkerParent: Map<string, Map<string, IAccessorEntry>>;
  /**
   * 翻訳された `for` のループ要素パス（`groups.*.children.*`）→ 翻訳で増えた
   * ワイルドカード数。イベントハンドラの「スコープ相対の添字」（§4-4 / P2-9）が
   * 引く — 添字列の末尾から (総数 − shift) 本だけが作者の見える添字。
   * translateParsedForMount が for の翻訳時に埋める。
   */
  readonly indexShiftByLoopElementPath: Map<string, number>;
  /**
   * この記録が親の getterPaths に追加したマーカーパス（recordAccessorSuffix）。
   * 記録の恒久破棄時に cleanupCollectedMountRecord が親から回収する。
   * record の外の消費者（FinalizationRegistry の held 値）も参照するため、
   * record 本体が回収された後も held 経由で読める独立オブジェクトにしてある。
   */
  readonly addedGetterPaths: Set<string>;
  /**
   * 公開 getter（docs/state-overlay-export-design.md X2 / X3）: 公開パス（マーカー無し・
   * `users.*.display`）→ マーカー親パス・接尾キー・マーカーパス。registerExports が
   * 初回登録で getter / setter キーから作る（翻訳できないアクセサは載らない）。
   */
  readonly exports: Map<string, IExportEntry>;
}

export interface IExportEntry {
  /** マーカーで終わるパス（`users.*.#m7` — overlay.ts の「マーカー親」。accessorBySuffixByMarkerParent の鍵） */
  readonly markerTerminalPath: string;
  readonly suffix: string;
  readonly markerPath: string;
  readonly exportedPath: string;
}

export interface IAccessorEntry {
  readonly accessorName: string;
  readonly indexShift: number;
}

let nextMountId = 0;

const MOUNT_DOLLAR_DECLARATIONS = [
  "$watch", STATE_STREAMS_NAME, "$scan", "$listKeys", STATE_UPDATED_CALLBACK_NAME, "$commandTokens", "$eventTokens", "$on",
  // $errorCallback もルート専用（要件 B11 — 以前は無言で無視していた）
  "$recursion", "$errorCallback",
] as const;
const dollarDeclarationWarned = new Set<string>();

/** テスト用: 宣言 warn の 1 回性台帳を空にする。 */
export function clearMountDollarWarnsForTesting(): void {
  dollarDeclarationWarned.clear();
}

/**
 * マウントされたコンポーネントは宣言面（`$watch` / `$streams` / `$listKeys` /
 * `$updatedCallback` / `$commandTokens` / `$eventTokens` / `$on`）を実行しない
 * （v1 の mapped も同じ — innerState が `$` を遮っていた）。無言に捨てず、
 * (tag, prop) につき 1 回だけ「ルート（または対応する宣言はボリューム）に宣言する」
 * 誘導を出す。テンプレート側の `$command.*` の**参照**（バインディングのパス）は
 * ルート宣言のトークンに解決される（`$` 頭のパスは翻訳しない — translateInnerPath）。
 * `$connectedCallback` / `$disconnectedCallback` / `$stateReadyCallback` は要素の
 * ライフサイクルとしてスコープごとに残る（設計書 §4-6）。
 */
export function warnMountedDollarDeclarations(record: IMountRecord): void {
  const declared: string[] = MOUNT_DOLLAR_DECLARATIONS.filter(
    (name) => typeof (record.stateObject as Record<string, unknown>)[name] !== "undefined",
  );
  // `**` getter（`get "node.**.total"()`）も同じ扱い。`markerizeAccessorPath` は `*` セグメントしか
  // 探さないので `**` を含むキーは私有アンカーに落ち、参照されないまま永久に登録されない
  // （ボリュームは接ぎ木前に拒否し、`$recursion` はこの誘導が出るのに、`**` getter だけが
  // 無言だった — 第 3 サイクルのレビューで実測）。
  for (const accessor of record.getterKeys) {
    if (accessor.indexOf(RECURSION_WILDCARD) !== -1) {
      declared.push(`"${accessor}"`);
    }
  }
  if (declared.length === 0) {
    return;
  }
  const key = `${record.component.tagName.toLowerCase()}|${record.stateProp}`;
  if (dollarDeclarationWarned.has(key)) {
    return;
  }
  dollarDeclarationWarned.add(key);
  console.warn(
    `[@wcstack/state] [wcs/mount-dollar-declaration] <${key.split("|")[0]}>.${record.stateProp} declares ` +
    `${declared.join(", ")}, which mounted components do not run. Declare them on the root state instead ` +
    `(a volume <wcs-state mount="..."> can host $watch / $listKeys / $updatedCallback; $recursion and ` +
    `"**" getters expand against the root tree). See docs/state-mount-design.md §4-6.`,
  );
}

/**
 * マウントされたコンポーネントのライフサイクル呼び出し（`$connectedCallback` /
 * `$disconnectedCallback`）。`this` は公開 chroot（`element[stateProp]`）。
 * 例外・reject は 1 コンポーネントに閉じる（切断時は親も切断中でありうる）。
 */
export function callMountLifecycleCallback(record: IMountRecord, name: string): void {
  const callback = (record.stateObject as Record<string, unknown>)[name];
  if (typeof callback !== "function") {
    return;
  }
  try {
    const chroot = (record.component as unknown as Record<string, unknown>)[record.stateProp];
    const result = (callback as (this: unknown) => unknown).call(chroot);
    if (result instanceof Promise) {
      result.catch((error) => {
        console.error(`[@wcstack/state] mounted <${record.component.tagName.toLowerCase()}> ${name} failed.`, error);
      });
    }
  } catch (error) {
    console.error(`[@wcstack/state] mounted <${record.component.tagName.toLowerCase()}> ${name} failed.`, error);
  }
}

/** テスト用: マーカー id を初期化する（マーカー文字列の安定化） */
export function resetMountIdForTesting(): void {
  nextMountId = 0;
}

function collectAccessorKeys(stateObject: Record<string, any>): { getterKeys: Set<string>, setterKeys: Set<string> } {
  const getterKeys = new Set<string>();
  const setterKeys = new Set<string>();
  const descriptors = Object.getOwnPropertyDescriptors(stateObject);
  for (const [key, descriptor] of Object.entries(descriptors)) {
    if (typeof descriptor.get === "function") getterKeys.add(key);
    if (typeof descriptor.set === "function") setterKeys.add(key);
  }
  return { getterKeys, setterKeys };
}

/**
 * ホストの `state[.sub]: path` バインディング群からマウント記録を組む。
 * `bindings` は propSegments[0] === stateProp で選別済みであること
 * （bindWebComponent が v1 の buildPrimaryMappingRule に渡すものと同じ集合）。
 */
export function buildMountRecord(
  component: Element,
  stateProp: string,
  bindings: readonly IBindingInfo[],
  parentStateElement: IStateElement,
  stateObject: Record<string, any>,
  injectedKeys: ReadonlySet<string> = new Set<string>(),
): IMountRecord {
  if (bindings.length === 0) {
    raiseError(`Cannot build a mount record without host bindings for "${stateProp}".`);
  }
  // 宣言キーの旧名を正式名へ（要件 B12）— 宣言の警告（MOUNT_DOLLAR_DECLARATIONS）は正式名で引く
  normalizeDeclarationAliases(stateObject);
  const entries: IMountEntry[] = [];
  const seenInnerPaths = new Set<string>();
  let rootEntry: IMountEntry | null = null;
  for (const binding of bindings) {
    const innerSegments = binding.propSegments.slice(1);
    const innerPath = innerSegments.join(DELIMITER);
    if (seenInnerPaths.has(innerPath)) {
      // 同じ内側パスを 2 つの規則が指す形はどちらが勝つか書き手に見えない（M6・Phase 1 と同じ）
      raiseError('Duplicate mapping rule for web component.');
    }
    seenInnerPaths.add(innerPath);
    const entry: IMountEntry = {
      innerSegments,
      outerPathInfo: binding.statePathInfo,
      readonly: binding.propModifiers?.includes(MODIFIER_READONLY) === true,
    };
    entries.push(entry);
    if (innerSegments.length === 0) {
      rootEntry = entry;
    }
  }
  entries.sort((a, b) => b.innerSegments.length - a.innerSegments.length);
  const id = ++nextMountId;
  const marker = `#m${id}`;
  const { getterKeys, setterKeys } = collectAccessorKeys(stateObject);
  // ホストが部分エントリで明示したキー（`state.theme: theme`）は、同名の own data key があっても
  // 私有にしない — 明示した配線が作者の既定値に勝つ（要件 B14 ②。以前は own key が勝ち、
  // ホストの値が届かなかった）
  const mappedKeys = new Set<string>();
  for (const entry of entries) {
    if (entry.innerSegments.length > 0) mappedKeys.add(entry.innerSegments[0]);
  }
  const privateSnapshot: Record<string, unknown> = {};
  for (const key of Object.keys(stateObject)) {
    if (key.startsWith("$")) continue;
    if (getterKeys.has(key) || setterKeys.has(key)) continue;
    if (typeof stateObject[key] === "function") continue;
    if (injectedKeys.has(key)) continue;
    if (mappedKeys.has(key)) continue;
    privateSnapshot[key] = stateObject[key];
  }
  return {
    id,
    marker,
    component,
    stateProp,
    parentStateElement,
    entries,
    rootEntry,
    delta: rootEntry === null ? 0 : rootEntry.outerPathInfo.wildcardCount,
    markerBasePath: rootEntry === null ? marker : rootEntry.outerPathInfo.path + DELIMITER + marker,
    stateObject,
    getterKeys,
    setterKeys,
    injectedKeys,
    mappedKeys,
    privateSnapshot,
    accessorBySuffixByMarkerParent: new Map(),
    indexShiftByLoopElementPath: new Map(),
    addedGetterPaths: new Set(),
    exports: new Map(),
  };
}

function firstSegmentOf(path: string): string {
  const dot = path.indexOf(DELIMITER);
  return dot === -1 ? path : path.slice(0, dot);
}

/** 規則 3 の一致: 最長接頭辞のエントリ（entries は長い順）。一致しなければ null。 */
function findTreeEntry(record: IMountRecord, segments: readonly string[]): IMountEntry | null {
  return findMountEntry(record.entries, segments);
}

/** 規則 3: 最長接頭辞一致でツリーの絶対パスへ翻訳する。一致しなければ null。 */
function translateTreePath(record: IMountRecord, segments: readonly string[]): string | null {
  const entry = findMountEntry(record.entries, segments);
  return entry === null ? null : translateByMountEntry(entry, segments);
}

/** 私有アンカー: パス全体をマーカーの下に置く（`users.*.#m.editing` / `users.*.#m.drafts.*.title`） */
function markerizePrivate(record: IMountRecord, innerPath: string): string {
  return record.markerBasePath + DELIMITER + innerPath;
}

/**
 * アクセサの逆引き（マーカー親 → 接尾キー → 作者のアクセサ名と $n シフト）を登録する。
 * suffix は常に非空（ワイルドカード終端アクセサは markerizeAccessorPath が raise 済み —
 * 空を許すと trailing dot の不正パスが getterPaths に載る）。
 */
function recordAccessorSuffix(record: IMountRecord, markerParentPath: string, suffix: string, accessorName: string): void {
  let bySuffix = record.accessorBySuffixByMarkerParent.get(markerParentPath);
  if (typeof bySuffix === "undefined") {
    bySuffix = new Map();
    record.accessorBySuffixByMarkerParent.set(markerParentPath, bySuffix);
  }
  const translatedPath = markerParentPath + DELIMITER + suffix;
  bySuffix.set(suffix, {
    accessorName,
    indexShift: getPathInfo(translatedPath).wildcardCount - getPathInfo(accessorName).wildcardCount,
  });
  if (record.getterKeys.has(accessorName)) {
    // マーカーパスを親の getterPaths に載せる。checkDependency（評価中の読み →
    // このアクセサの動的エッジ登録）と isCacheable（getter 値のキャッシュ）が
    // getterPaths を正本にしているため、載せないと再評価もキャッシュも効かない。
    // モック互換のため optional に扱う。追加分は記録の恒久破棄時に回収する
    // ため addedGetterPaths にも控える（cleanupCollectedMountRecord）。
    // suffix 空を素朴に結合すると trailing dot の不正パスになる — translatedPath を使う
    (record.parentStateElement.getterPaths as Set<string> | undefined)?.add(translatedPath);
    record.addedGetterPaths.add(translatedPath);
  }
}

/**
 * ワイルドカードを含む getter / setter のマーカー位置決め。ワイルドカード接頭辞が
 * ツリーに翻訳できるなら、その直後にマーカーを挟む（ループ文脈と listIndex の arity を
 * 素の wildcard getter と同一に保つ）。先頭セグメントが私有ならパスごと私有アンカー。
 */
function markerizeAccessorPath(record: IMountRecord, innerPath: string): string {
  const segments = innerPath.split(DELIMITER);
  let lastWildcard = -1;
  for (let i = segments.length - 1; i >= 0; i--) {
    if (segments[i] === WILDCARD) {
      lastWildcard = i;
      break;
    }
  }
  if (lastWildcard === -1) {
    recordAccessorSuffix(record, record.markerBasePath, innerPath, innerPath);
    return markerizePrivate(record, innerPath);
  }
  const first = segments[0];
  if (isPrivateAnchor(record, first)) {
    recordAccessorSuffix(record, record.markerBasePath, innerPath, innerPath);
    return markerizePrivate(record, innerPath);
  }
  const treeSegments = segments.slice(0, lastWildcard + 1);
  const rest = segments.slice(lastWildcard + 1);
  const translated = translateTreePath(record, treeSegments);
  if (translated === null) {
    // 部分マウントのみで、どの接頭辞にも含まれないツリー部（§4-1 の 4b）
    raiseError(noMountEntryMessage(record, innerPath));
  }
  if (rest.length === 0) {
    // ワイルドカード終端アクセサ（行 getter `get "tags.*"()`）がツリーのリストへ翻訳される形:
    // 翻訳結果がマーカー終端パス（`users.*.tags.*.#m`）になり、getByAddress のオーバーレイ
    // dispatch が getter 評価より先に掛かってオーバーレイ proxy が値として返る
    // （作者の getter は評価されない）。無言で壊れる形なのでサポート外として loud に落とす
    raiseError(
      `Wildcard-terminal accessor "${innerPath}" on mounted <${record.component.tagName.toLowerCase()}> ` +
      `is not supported: it translates to a marker-terminal path where the mount overlay would shadow ` +
      `the accessor. Declare the row value as a getter on the host tree, or back it with a ` +
      `component-own array (a private key makes the whole path private).`,
    );
  }
  const markerParent = translated + DELIMITER + record.marker;
  recordAccessorSuffix(record, markerParent, rest.join(DELIMITER), innerPath);
  return markerParent + DELIMITER + rest.join(DELIMITER);
}

/** 先頭セグメントが「作者のもの」（own data key・メソッド。積みで注入されたキーは除く）か */
function isPrivateAnchor(record: IMountRecord, firstSegment: string): boolean {
  if (record.injectedKeys.has(firstSegment) || record.mappedKeys.has(firstSegment)) {
    return false;
  }
  if (typeof record.stateObject[firstSegment] === "function" && !record.getterKeys.has(firstSegment)) {
    return true;
  }
  return Object.prototype.hasOwnProperty.call(record.stateObject, firstSegment)
    && !record.getterKeys.has(firstSegment)
    && !record.setterKeys.has(firstSegment);
}

function noMountEntryMessage(record: IMountRecord, innerPath: string): string {
  return `Path "${innerPath}" in <${record.component.tagName.toLowerCase()}> does not resolve: ` +
    `it is not an own key of the component state and no mount entry covers it ` +
    `(mounted prefixes: ${record.entries.filter(e => e.innerSegments.length > 0).map(e => e.innerSegments.join(DELIMITER)).join(", ")}). ` +
    `Mount it from the host ("${record.stateProp}: path" / "${record.stateProp}.${firstSegmentOf(innerPath)}: path") or declare the key on the component state.`;
}

/**
 * コンポーネントスコープの内側パスを、親ツリーの絶対パスへ翻訳する（設計書 §4-1）。
 *
 * 1. getter / setter（完全一致・またはワイルドカード getter）→ マーカーパス（chroot 評価）
 * 2. own data key（部分規則が覆わないもの）・メソッド → マーカーパス（私有）
 * 3. それ以外 → 最長接頭辞一致でツリーへ
 * 4. 一致なし: ルートエントリがあれば必ず 3 で一致する。無ければ throw（4b）
 *
 * `$`（予約名前空間・`$1` 等）と `#`（構造プレースホルダ）で始まるパスは翻訳しない。
 */
const INDEX_PATH_REGEX = /^\$(\d+)$/;

/**
 * `$n` バインディングのスコープ補正量（D9・設計書 §4-4）。
 * 囲む `for` の内側なら「その for パスが翻訳で得たワイルドカード数」— 行マウント
 * （`state: .`）の `for: tags` は `users.*.tags` になり +1、部分マウント
 * `state.items: groups.*.children` の `for: items` も +1。for の外（スコープ直下）は
 * ルート接頭辞の Δ。翻訳がワイルドカードを増やさないマウント（`state: user`）は 0。
 */
export function getIndexShiftForScope(record: IMountRecord, forPath: string | undefined): number {
  if (typeof forPath === "undefined") {
    return record.delta;
  }
  const translated = translateInnerPath(record, forPath);
  return getPathInfo(translated).wildcardCount - getPathInfo(forPath).wildcardCount;
}

/**
 * `innerPath` がツリーへ翻訳され、その先のエントリが読み取り専用（`#ro`）か（要件 B14 ①）。
 * 私有キー・アクセサ・`$` / `#` で始まるパスはコンポーネント自身のものなので対象外。
 */
function isReadonlyTreePath(record: IMountRecord, innerPath: string): IMountEntry | null {
  const head = innerPath[0];
  if (head === "$" || head === "#") return null;
  if (record.getterKeys.has(innerPath) || record.setterKeys.has(innerPath)) return null;
  const first = firstSegmentOf(innerPath);
  if (record.getterKeys.has(first) || record.setterKeys.has(first) || isPrivateAnchor(record, first)) return null;
  const entry = findTreeEntry(record, innerPath.split(DELIMITER));
  return entry !== null && entry.readonly ? entry : null;
}

/**
 * 書き込みの翻訳（要件 B14 ①）。`translateInnerPath` と同じ行き先を返すが、読み取り専用で
 * マウントされたエントリ（`state#ro: user`）を通るツリーへの書き込みは名指しで拒否する。
 * コンポーネント側の書き込みの入口（`element.state`・オーバーレイ・`$setAll` / `$resolve`）が呼ぶ。
 */
export function translateInnerWritePath(record: IMountRecord, innerPath: string): string {
  const readonlyEntry = isReadonlyTreePath(record, innerPath);
  if (readonlyEntry !== null) {
    const suffix = readonlyEntry.innerSegments.length === 0 ? "" : DELIMITER + readonlyEntry.innerSegments.join(DELIMITER);
    raiseError(
      `[wcs/mount-readonly] <${record.component.tagName.toLowerCase()}> cannot write "${innerPath}": ` +
      `it is mounted read-only ("${record.stateProp}${suffix}#${MODIFIER_READONLY}: ${readonlyEntry.outerPathInfo.path}"). ` +
      `Write it on the host, or drop #${MODIFIER_READONLY} from the mount.`,
    );
  }
  return translateInnerPath(record, innerPath);
}

export function translateInnerPath(record: IMountRecord, innerPath: string): string {
  const head = innerPath[0];
  if (head === "$" || head === "#") {
    // `$` の予約名前空間はパスとしては翻訳しない（`$n` のスコープ補正は
    // translateParsedForMount が囲む for の文脈で行う。getter 内の `this.$1` は
    // 親トラップがアクセサの indexShift で補正する）
    return innerPath;
  }
  // 規則 1: 完全一致の getter / setter（`display`・`"children.*.label"`）
  if (record.getterKeys.has(innerPath) || record.setterKeys.has(innerPath)) {
    return markerizeAccessorPath(record, innerPath);
  }
  const first = firstSegmentOf(innerPath);
  // 規則 1'/2: 先頭セグメントが getter / setter / メソッド / own data key → マーカー配下
  if (record.getterKeys.has(first) || record.setterKeys.has(first)) {
    return markerizePrivate(record, innerPath);
  }
  if (isPrivateAnchor(record, first)) {
    return markerizePrivate(record, innerPath);
  }
  // 規則 3: ツリー
  const translated = translateTreePath(record, innerPath.split(DELIMITER));
  if (translated !== null) {
    return translated;
  }
  // 規則 4b: 部分マウントのみで一致なし
  raiseError(noMountEntryMessage(record, innerPath));
}

interface ITranslatable {
  readonly statePathName: string;
  readonly statePathInfo: IPathInfo;
}

/**
 * パース結果 / バインディングをマウント先の形へ変換した複製を返す
 * （パース結果キャッシュは触らない）。解決サイト（applyChangeFromBindings /
 * getAbsoluteStateAddressByBinding / fragmentInfoByUUID）は rootNode で
 * state element を引く — スコープ根は台帳エイリアスで親ツリーに到達する。
 */
export function translateParsedForMount<T extends ITranslatable>(record: IMountRecord, parsed: T, forPath?: string): T {
  let translated: string;
  const indexMatch = INDEX_PATH_REGEX.exec(parsed.statePathName);
  if (indexMatch !== null) {
    // `$n` はスコープ相対（D9・§4-4）: 囲む for の翻訳で増えたワイルドカード数だけ繰り上げる
    const shift = getIndexShiftForScope(record, forPath);
    translated = shift === 0 ? parsed.statePathName : `$${Number(indexMatch[1]) + shift}`;
  } else {
    translated = translateInnerPath(record, parsed.statePathName);
    if ((parsed as { bindingType?: string }).bindingType === "for") {
      // スコープ相対の添字（P2-9）用: この for の行に立つループ文脈の要素パスと、
      // 翻訳で増えたワイルドカード数を控える。shift 0（Δ=0 の丸ごとマウント
      // `state: user` や同名翻訳の部分マウント）でも必ず載せる —
      // event/handler.ts は台帳に無いループ文脈を「外側スコープの借用行＝
      // 添字 0 本」と解釈するため、登録漏れは自スコープの for の添字を
      // 丸ごと落とす（§4-4 違反）
      const shift = getPathInfo(translated).wildcardCount - parsed.statePathInfo.wildcardCount;
      record.indexShiftByLoopElementPath.set(translated + DELIMITER + WILDCARD, shift);
    }
  }
  // 読み取り専用のマウント（要件 B14 ①）を通る束縛は、要素 → state の書き戻しを止める（`#ro` と同じ）
  const modifiers = (parsed as { propModifiers?: readonly string[] }).propModifiers;
  const forceReadonly = indexMatch === null && Array.isArray(modifiers)
    && !modifiers.includes(MODIFIER_READONLY)
    && isReadonlyTreePath(record, parsed.statePathName) !== null;
  if (translated === parsed.statePathName && !forceReadonly) {
    return parsed;
  }
  return {
    ...parsed,
    statePathName: translated,
    statePathInfo: getPathInfo(translated),
    ...(forceReadonly ? { propModifiers: [...modifiers!, MODIFIER_READONLY] } : {}),
  };
}

export function translateBindingForMount(record: IMountRecord, binding: IBindingInfo, forPath?: string): IBindingInfo {
  return translateParsedForMount(record, binding, forPath);
}

/**
 * マーカーパスのアクセサ評価中の `$n` シフト（トラップの補正が引く）。
 * アクセサとして登録されたパスならその indexShift、そうでなければルートの Δ。
 */
export function getIndexShiftForMarkerPath(record: IMountRecord, markerPath: string): number {
  // 末尾マーカーをセグメント単位で正確に切り出す（getMountRecordByPath と同じ規則）。
  // indexOf(record.marker) の前方一致だと `#m2` が別記録の `#m21` の中に誤ヒットし、
  // 親パスをセグメント途中で切って登録簿の照会を外す（Δ への誤フォールバック）
  const hashIndex = markerPath.lastIndexOf("#");
  if (hashIndex === -1) {
    return record.delta;
  }
  const end = markerPath.indexOf(DELIMITER, hashIndex);
  const marker = end === -1 ? markerPath.slice(hashIndex) : markerPath.slice(hashIndex, end);
  if (marker !== record.marker) {
    return record.delta;
  }
  const parent = end === -1 ? markerPath : markerPath.slice(0, end);
  const suffix = end === -1 ? "" : markerPath.slice(end + 1);
  const entry = record.accessorBySuffixByMarkerParent.get(parent)?.get(suffix);
  return typeof entry !== "undefined" ? entry.indexShift : record.delta;
}

/**
 * `$getAll` / `$setAll` / `$resolve` の接頭辞翻訳（§4-6 / P2-9）: 作者のスコープ相対
 * indexes の先頭に、翻訳で増えたワイルドカード分の文脈添字を合成する。
 * contextIndexes はホスト要素（chroot）またはマーカーアドレス（オーバーレイ）の
 * listIndex 添字列。プレフィックスが増えないパス（Δ=0 の翻訳）は素通し。
 */
export function composeMountIndexes(
  record: IMountRecord,
  innerPath: string,
  translatedPath: string,
  indexes: readonly number[] | undefined,
  contextIndexes: readonly number[],
): readonly number[] | undefined {
  if (typeof indexes === "undefined") {
    return undefined;
  }
  const prefixWildcards = getPathInfo(translatedPath).wildcardCount - getPathInfo(innerPath).wildcardCount;
  if (prefixWildcards === 0) {
    return indexes;
  }
  if (contextIndexes.length < prefixWildcards) {
    raiseError(
      `Cannot resolve "${innerPath}" from this mount: the mounted prefix has ${prefixWildcards} wildcard(s) ` +
      `but the host context provides only ${contextIndexes.length} index(es).`,
    );
  }
  return [...contextIndexes.slice(0, prefixWildcards), ...indexes];
}

// ---------------------------------------------------------------------------
// 登録簿
// ---------------------------------------------------------------------------

/**
 * スコープ根 → マウント記録。キーは Shadow DOM 形ならコンポーネントの shadowRoot、
 * Light DOM 形ならコンポーネント要素自身（そのサブツリーがスコープ）。
 */
const mountRecordByScopeRoot = new WeakMap<Node, IMountRecord>();

/**
 * コンポーネント要素 → stateProp → マウント記録。
 * connectedCallback で shadow の innerHTML を張り直す作りのコンポーネントでは、
 * 再接続のたびに新しい <wcs-state> が同じ shadowRoot に入り、スコープが再初期化される。
 * 記録を要素単位で再利用することでマーカーが安定し、親側の登録簿
 * （byMarker・getterPaths）が再接続のたびに増えない。stateObject はクラスフィールド
 * なので要素と同寿命 — 記録の前提（作者のオブジェクトの同一性）が保たれる。
 */
const mountRecordByComponent = new WeakMap<Element, Map<string, IMountRecord>>();

/** 再初期化用: この要素の stateProp に対して登録済みの記録を引く。 */
export function getRegisteredMountRecord(component: Element, stateProp: string): IMountRecord | null {
  return mountRecordByComponent.get(component)?.get(stateProp) ?? null;
}

/**
 * 親 state element → マーカー → マウント記録（オーバーレイ dispatch と Δ 補正が引く）。
 *
 * 値は **WeakRef**（B6）。記録への強参照は要素キーの WeakMap
 * （mountRecordByComponent / mountRecordByScopeRoot）だけが持つので、記録は
 * コンポーネント要素と同寿命になる — プール返却では要素が生きているので記録も生き、
 * 恒久破棄（route swap / `if` で捨てた形）では要素ごと回収可能になる。
 * ここを強参照にすると、長寿命の親 state 要素に破棄済み要素（と Shadow サブツリー）が
 * 際限なく蓄積する。
 */
const mountRecordsByStateElement = new WeakMap<IStateElement, Map<string, WeakRef<IMountRecord>>>();

/** FinalizationRegistry の held 値: 記録が回収された後に台帳から掃除するもの。 */
export interface ICollectedMountLedgers {
  readonly byMarker: Map<string, WeakRef<IMountRecord>>;
  readonly marker: string;
  readonly getterPaths: Set<string> | undefined;
  readonly addedGetterPaths: ReadonlySet<string>;
}

/**
 * 恒久破棄されたマウント記録の台帳掃除（FinalizationRegistry のコールバック本体）。
 * マーカーは記録ごとに一意（`#m<id>` 単調増加）なので、発火時点でこのマーカーの
 * エントリは死んだ WeakRef のはず — 生きていれば触らない（防御）。
 * エクスポートしているのは GC を強制できないテスト環境で直接検証するため。
 */
export function cleanupCollectedMountRecord(held: ICollectedMountLedgers): void {
  const ref = held.byMarker.get(held.marker);
  if (typeof ref !== "undefined" && typeof ref.deref() === "undefined") {
    held.byMarker.delete(held.marker);
  }
  if (typeof held.getterPaths !== "undefined") {
    for (const path of held.addedGetterPaths) {
      held.getterPaths.delete(path);
    }
  }
}

const collectedMountRegistry = new FinalizationRegistry<ICollectedMountLedgers>(cleanupCollectedMountRecord);

/** マウント記録 → スコープ根。行 content をその場で使い回したときの張り直しが引く（#4） */
const scopeRootByMountRecord: WeakMap<IMountRecord, Node> = new WeakMap();

export function getScopeRootByMountRecord(record: IMountRecord): Node | null {
  return scopeRootByMountRecord.get(record) ?? null;
}

// ループ文脈の探索がマウントされた ShadowRoot でホストへ抜ける受け口（list/loopContextByNode.ts）。
// 最初の記録の登録で 1 回だけ注入する（マウントの無いページでは探索は境界で止まったまま）
let scopeHostInstalled = false;
function installMountedScopeHost(): void {
  if (scopeHostInstalled) return;
  scopeHostInstalled = true;
  setMountedScopeHost((root) => mountRecordByScopeRoot.has(root) ? root.host : null);
}

export function registerMountRecord(scopeRoot: Node, record: IMountRecord): void {
  installMountedScopeHost();
  mountRecordByScopeRoot.set(scopeRoot, record);
  scopeRootByMountRecord.set(record, scopeRoot);
  let byMarker = mountRecordsByStateElement.get(record.parentStateElement);
  if (typeof byMarker === "undefined") {
    byMarker = new Map();
    mountRecordsByStateElement.set(record.parentStateElement, byMarker);
  }
  byMarker.set(record.marker, new WeakRef(record));
  let byProp = mountRecordByComponent.get(record.component);
  if (typeof byProp === 'undefined') {
    byProp = new Map();
    mountRecordByComponent.set(record.component, byProp);
  }
  const isFirstRegistration = byProp.get(record.stateProp) !== record;
  byProp.set(record.stateProp, record);
  if (isFirstRegistration) {
    // 恒久破棄で台帳（byMarker・親 getterPaths への追加分）を回収する（B6）。
    // 再初期化（同一 record の再登録 — マーカー安定のための再利用）では二重登録しない
    collectedMountRegistry.register(record, {
      byMarker,
      marker: record.marker,
      getterPaths: record.parentStateElement.getterPaths as Set<string> | undefined,
      addedGetterPaths: record.addedGetterPaths,
    });
  }
  // D18: マウントの無い state はオーバーレイ dispatch を boolean 1 個で抜ける
  record.parentStateElement.markHasMounts?.();
}

export function getMountRecordByScopeRoot(scopeRoot: Node): IMountRecord | null {
  return mountRecordByScopeRoot.get(scopeRoot) ?? null;
}

/**
 * ノードから最も近いマウントスコープ根の記録を引く（event/handler.ts のスコープ相対
 * 添字が使う）。Light DOM 形はスコープ根＝**コンポーネント要素自身**（D7・
 * mountScope.ts）で rootNode の内側に入れ子になりうる（Shadow 形のスコープの中の
 * Light DOM マウント）ため、**祖先を先に**辿って最初のスコープ根を探す — rootNode
 * 直ヒットを先に返すと外側の記録を取り違える。祖先に無ければ rootNode 自身
 * （Shadow DOM 形のスコープ根＝shadowRoot）で引く。入れ子マウントでは
 * 最も内側（＝そのノードのバインディングを翻訳した記録）が返る。
 * `hasMounts` が真のときだけ呼ぶこと（無マウントの経路にこの走査を載せない — D18）。
 */
export function findMountRecordForNode(node: Node, rootNode: Node): IMountRecord | null {
  let current: Node | null = node;
  while (current !== null && current !== rootNode) {
    const record = mountRecordByScopeRoot.get(current);
    if (typeof record !== "undefined") {
      return record;
    }
    current = current.parentNode;
  }
  return mountRecordByScopeRoot.get(rootNode) ?? null;
}

/** この state element に登録済みのマウント記録を列挙する（devtools の overlays が読む）。 */
export function getMountRecordsForStateElement(stateElement: IStateElement): IMountRecord[] {
  const byMarker = mountRecordsByStateElement.get(stateElement);
  if (typeof byMarker === "undefined") {
    return [];
  }
  const records: IMountRecord[] = [];
  for (const ref of byMarker.values()) {
    const record = ref.deref();
    if (typeof record !== "undefined") {
      records.push(record);
    }
  }
  return records;
}

/** 親 state element がマウントを 1 つでも持つか（D18: 無ければ dispatch は分岐 1 つで抜ける） */
export function stateElementHasMounts(stateElement: IStateElement): boolean {
  const byMarker = mountRecordsByStateElement.get(stateElement);
  return typeof byMarker !== "undefined" && byMarker.size > 0;
}

/**
 * パスに含まれるマーカーからマウント記録を引く。`hasMounts` が真のときだけ呼ぶこと。
 * `#` を含まないパス（圧倒的多数）は lastIndexOf 1 回で抜ける。
 * 入れ子マウント（外側の私有キーの上に内側マウントが載る形）ではパスに複数の
 * マーカーが並ぶ（`users.*.#m1.drafts.#m2`）— オーバーレイ dispatch と $n 補正が
 * 要るのは**末尾**のマーカーの記録なので、先頭でなく最後の `#` で切る
 * （先頭で切ると外側の記録が返り誤翻訳する）。
 */
export function getMountRecordByPath(stateElement: IStateElement, path: string): IMountRecord | null {
  const hashIndex = path.lastIndexOf("#");
  if (hashIndex === -1) {
    return null;
  }
  const byMarker = mountRecordsByStateElement.get(stateElement);
  if (typeof byMarker === "undefined") {
    return null;
  }
  const end = path.indexOf(DELIMITER, hashIndex);
  const marker = end === -1 ? path.slice(hashIndex) : path.slice(hashIndex, end);
  const ref = byMarker.get(marker);
  if (typeof ref === "undefined") {
    return null;
  }
  const record = ref.deref();
  if (typeof record === "undefined") {
    // 記録は回収済み（finalizer 発火前の窓）— 遅延 prune
    byMarker.delete(marker);
    return null;
  }
  return record;
}

/** テスト用: マーカー台帳の WeakRef を差し替える（GC を強制できない環境で死んだ参照を再現する）。 */
export function _setMountRecordRefForTesting(
  stateElement: IStateElement,
  marker: string,
  ref: WeakRef<IMountRecord>,
): void {
  mountRecordsByStateElement.get(stateElement)?.set(marker, ref);
}
